import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa v2.0 x-thread (English)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v2.0/x-thread-en.md","filePath":"announcements/v2.0/x-thread-en.md"}'),o={name:"announcements/v2.0/x-thread-en.md"};function i(s,e,d,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="kiwa-v2-0-x-thread-english" tabindex="-1">kiwa v2.0 x-thread (English) <a class="header-anchor" href="#kiwa-v2-0-x-thread-english" aria-label="Permalink to &quot;kiwa v2.0 x-thread (English)&quot;">​</a></h1><h2 id="tweet-1" tabindex="-1">Tweet 1 <a class="header-anchor" href="#tweet-1" aria-label="Permalink to &quot;Tweet 1&quot;">​</a></h2><p>kiwa v2.0 is out — <strong>brand shortening rename</strong>. All 41 kiwa packages migrated from <code>@kiwa-test/*</code> to <code>@kiwa-lab/*</code> with a synchronized v2.0.0 major bump. API 0 changes, shape contract preserving, backward compat absolute (deprecated re-export 6-month grace window, 2026-07-08 → 2027-01-08).</p><h2 id="tweet-2" tabindex="-1">Tweet 2 <a class="header-anchor" href="#tweet-2" aria-label="Permalink to &quot;Tweet 2&quot;">​</a></h2><p>Pure rename milestone, 5 PR exception expansion (4 PR rhythm paused only for rename milestone, resumes at v2.1+). 1424 file + 900+ reference changes across packages / workspace internal dep / docs / dogfood / tests. Zero semantic changes.</p><h2 id="tweet-3" tabindex="-1">Tweet 3 <a class="header-anchor" href="#tweet-3" aria-label="Permalink to &quot;Tweet 3&quot;">​</a></h2><p><code>pnpm add -D @kiwa-lab/core@^2.0</code> for new consumers. Existing consumers can migrate immediately (sed replace) or use the 6-month grace period (@kiwa-test/* v2.0.0 deprecated shim publishes @kiwa-lab/* as re-export).</p><h2 id="tweet-4" tabindex="-1">Tweet 4 <a class="header-anchor" href="#tweet-4" aria-label="Permalink to &quot;Tweet 4&quot;">​</a></h2><p>Why rename: <code>@kiwa-test/*</code> implied test-only scope, mismatches future scope expansion. <code>@kiwa-lab/*</code> is shorter, more brand-aligned. 45 milestone streak + depth-5 3rd case + depth-6 2nd case candidate compound assets continue in kiwa brand.</p><p>Lean formal verification integration comes as a separate library later, kiwa core stays testing-focused.</p><p>Migration: <a href="https://cardene777.github.io/kiwa/migrations/v2.0-rename-plan" target="_blank" rel="noreferrer">https://cardene777.github.io/kiwa/migrations/v2.0-rename-plan</a></p><p>#kiwa #v2 #rename #testing #vitest</p>',12)])])}const w=a(o,[["render",i]]);export{m as __pageData,w as default};
